/**
 * The scoring key for the Worker API.
 *
 * `worker/scoring-key.json` is generated by `bun run build:scoring-key` from the
 * committed instrument files. The API cannot read the app registry, because
 * `import.meta.glob` is a Vite feature.
 */
import { z } from "zod";

import type {
  ScaleKind,
  ScoringKey,
  ScoringKeyInstrument,
} from "../app/lib/instruments/scoring-key";
import key from "./scoring-key.json";

const scoringKeyInstrumentSchema = z
  .object({
    contentHash: z.string().min(1),
    itemCounts: z.record(z.string().min(1), z.number().int().positive()),
    kind: z.enum(["facet", "domain"]),
    scale: z
      .object({
        max: z.number().int().min(1),
        min: z.number().int().min(0),
      })
      .strict(),
  })
  .strict();

const scoringKeySchema = z
  .object({
    instruments: z.record(z.string().min(1), scoringKeyInstrumentSchema),
  })
  .strict();

/** Parsed at module load, so a damaged key fails the deploy instead of a request. */
export const scoringKey: ScoringKey = scoringKeySchema.parse(key);

export const findKeyInstrument = (
  instrumentId: string
): ScoringKeyInstrument | null =>
  Object.hasOwn(scoringKey.instruments, instrumentId)
    ? scoringKey.instruments[instrumentId]
    : null;

/**
 * Checks a score table against one instrument. Returns a message when the table
 * cannot belong to that instrument, and `null` when it can.
 *
 * The check covers the shape and the range, not the truth. The API never sees
 * the answers, so it cannot prove that a sum came from them.
 */
export const validateScores = (
  instrument: ScoringKeyInstrument,
  scaleKind: ScaleKind,
  scores: Record<string, number>
): string | null => {
  if (instrument.kind !== scaleKind) {
    return `This test stores ${instrument.kind} scores.`;
  }

  const expected = Object.keys(instrument.itemCounts).toSorted();
  const given = Object.keys(scores).toSorted();

  if (
    expected.length !== given.length ||
    expected.some((id, index) => id !== given[index])
  ) {
    return "The score keys do not match the test.";
  }

  for (const [id, itemCount] of Object.entries(instrument.itemCounts)) {
    const value = scores[id];
    const min = itemCount * instrument.scale.min;
    const max = itemCount * instrument.scale.max;

    if (
      value === undefined ||
      !Number.isInteger(value) ||
      value < min ||
      value > max
    ) {
      return `The score for ${id} is outside its range.`;
    }
  }

  return null;
};
